<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Memverifikasi | OPTIMA</title><style>body{font-family:system-ui;background:#f5f7fa;display:grid;place-items:center;min-height:100vh;color:#17324d}.box{text-align:center;background:white;padding:36px;border-radius:16px;border:1px solid #dce4eb}</style></head><body><div class="box"><h2>Memverifikasi akun...</h2><p id="message">Mohon tunggu sebentar.</p></div><script>const hash=new URLSearchParams(location.hash.slice(1));const payload={access_token:hash.get('access_token'),refresh_token:hash.get('refresh_token'),expires_in:Number(hash.get('expires_in')||0)};if(!payload.access_token){document.getElementById('message').textContent='Token login tidak ditemukan.'}else{fetch(@json(route('auth.session')),{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Accept':'application/json'},body:JSON.stringify(payload)}).then(r=>{if(r.redirected){location.href=r.url;return}if(r.ok){location.href=@json(route('dashboard'));return}throw new Error()}).catch(()=>document.getElementById('message').textContent='Sesi tidak dapat dibuat. Silakan kembali ke halaman login.');}</script></body></html>
